/*jshint esversion: 6 */
pc.script.createLoadingScreen(function(app) {

    // -------------- SETTINGS ---------------
    // ------------- Background --------------
    // Possible Mode Values
    const BG_COLOR = 'BG_COLOR'; // Default value, not used
    const BG_GRADIENT = 'BG_GRADIENT';
    const BG_REPEAT = 'BG_REPEAT'; // Set imageSource.backgroundRepeat
    const BG_IMAGE = 'BG_IMAGE'; // Set imageSource.backgroundImage

    const BG_MODE = 'BG_GRADIENT'; // <- Set background mode

        // IF BG_COLOR:
        const BG_COLOR_VALUE = '#ffffff'; // <- Set color

        // IF BG_GRADIENT:
        const GRADIENT_ROTATION = parseFloat('0.0'); // <- Set rotation (in deg, clock-wise)
        const BG_GRADIENT_START = '#00bffa'; // <- Set Color
        const BG_GRADIENT_END = '#015ee9'; // <- Set Color

    // ----------- Background Glow -----------
    const BG_GLOW = ('false' === 'true'); // <- Enable background glow, default value: false
    const GLOW_SCALE = parseFloat('0.25'); // <- Set scale (2.3 is standard), default value: 1
    const GLOW_H_POSITION = parseInt('0'); // <- Set horizontal pos (in px; > 0 moves the element to the RIGHT), default value: 0

    // ----------- Primary Logo --------------
    const LOGO_PRIMARY = ('true' === 'true'); // <- Enable primary logo, default value: false
    const LOGO_MAX_HEIGHT = parseInt('538'); // <- Set max-width (in px), default value: 200
    const LOGO_SCALE = parseFloat('80.0'); // <- Set scale (in percent), if two logo set max to 50%, default value: 80.0
    const LOGO_H_POSITION = parseFloat('0.0'); // <- Set horizontal pos (in %; > 0 = to the RIGHT), default value: 0
    const LOGO_BOTTOM_DISTANCE = parseInt('40'); // <- Set bottom distance (in px), default value: 40

    // ---------- Second Logo Image ----------
    const LOGO_SECONDARY = false; // <- Enable second logo image
    const SECOND_LOGO_SCALE = 50; // <- Set scale (in percent)
    const SECOND_LOGO_H_POSITION = 0; // <- Set horizontal pos (in px; > 0 = to the RIGHT)
    const SECOND_LOGO_BOTTOM_DISTANCE = 0; // <- Set bottom distance (in px)

    // ----------- Progress Bar --------------
    // Do you want to use images for progress bar?
    const USE_IMAGES = ('true' === 'true'); // <- Set if you want to use images for the background, border and progress, default value: false
    const SHOW_BORDER = ('false' === 'true'); // <- Does the bar have a border? (image or color), default value: false
    const OFFSET_X = parseFloat('0.0'); // <- Set x offset (in percent), default value: 0
    const OFFSET_Y = parseFloat('0.0'); // <- Set y offset (in percent), default value: 0
    // IF USE_IMAGES:
    const MAX_BAR_HEIGHT = parseInt('100'); // <- The max bar height (in px), default value: 60
    const MIN_BAR_HEIGHT = parseInt('100'); // <- The min bar height (in px), default value: 30

        // !!! FOLLOWING SETTINGS APPLY ONLY IF YOU USE HTML AND CSS FOR THE PROGRESS BAR RATHER THAN IMAGES
        // IF !USE_IMAGES:
        const RADIUS = parseInt('0'); // Set border radius of all progress bar parts, default value: 0

        // ------- Progress Bar Background ----------
        // Possible Mode Values
        const PB_COLOR = 'PB_COLOR';
        const PB_GRADIENT = 'PB_GRADIENT';

        const PB_MODE = 'PB_COLOR'; // <- Set progress bar BACKGROUND

            // IF PB_COLOR
            const PB_COLOR_VALUE = '#574b90'; // <- Set Color

            // IF PB_GRADIENT
            const PB_GRADIENT_ROTATION = parseFloat('90.0'); // <- Set rotation (in deg, clock-wise), default value: 90
            const PB_GRADIENT_START = '#467036'; // <- Set Color, default value: '#467036'
            const PB_GRADIENT_END = '#2442ad'; // <- Set Color, default value: '#2442ad'

        // ------- Progress Bar Border ----------
        const BORDER_COLOR_VALUE = '#ffffff'; // <- Set BORDER color, default value: '#ffffff'
        const BORDER_WIDTH = parseInt('5'); // <- Set border width (in px), default value: 5

        // ------------ Bar ---------------------
        // Possible Bar Filling Mode Values
        const BAR_COLOR = 'BAR_COLOR';
        const BAR_GRADIENT = 'BAR_GRADIENT';

        const BAR_MODE = 'BAR_COLOR'; // <- Set bar FILLING
        const TWEEN_PROGRESS = ('false' === 'true'); // <- Set tweening of bar (set to false if you use a runner) still WIP, default value: false

            // IF BAR_COLOR
            const BAR_COLOR_VALUE = '#fc85ae'; // <- Set Color, default value: '#fc85ae'
            // IF BAR_GRADIENT
            const BAR_GRADIENT_ROTATION = parseFloat('90.0'); // <- Set rotation (in deg, clock-wise), default value: 90
            const BAR_GRADIENT_START = '#000000'; // <- Set Color, default value: '#000000'
            const BAR_GRADIENT_END = '#2442ad'; // <- Set Color, default value: '#2442ad'

    // ------------ Runner -------------------
    const RUNNER = ('false' === 'true'); // <- Enable runner, default value: false
    const GLOSS = ('true' === 'true'); // <- Enable gloss, default value: true
    const RUNNER_ANIMATION = ('true' === 'true'); // <- Enable runner rotation, default value: true
    const RUNNER_HEIGHT = parseFloat('160.0'); // <- Set runner height (in percent), default value: 160

    // ------------ Fixed Image --------------
    const FIXED_IMAGE = false; // <- Enable fixed image
    const X_HEIGHT = 15;

    // ------------ Image Sources ------------
    const imageSource = {
        backgroundImage: '>>>bg_img<<<',
        backgroundRepeat: '>>>bg_repeat_img<<<',
        backgroundGlow: 'data:image/png;base64,',
        logo: 'data:image/png;base64,',
        // logo2: '',
        pbBackground: 'data:image/png;base64,',
        pbBorder: '>>>pb_border_img<<<',
        bar: 'data:image/png;base64,',
        runner: '>>>runner_img<<<',
        runnerGloss: '>>>runner_gloss_img<<<',
        // HA150 specific, only used when FIXED_IMAGE is set to true
        fixedImage: '',
        fixedBackground: '',
        fixedLogo: '',
    };
    // Pixel ratio to fix the loading bar on iOS, e.g. "400/64".
    const pbBgPixelRatio = '678/83';

    

    const autoHideLoadingScreen = ('true' === 'true');

    // ------------- SETTINGS END ------------


    let splashElem = {}, runnerContainerElem = {}, maskElem = {};

    const showLoadingScreen = () =>
    {
        console.log(
            '%c 🕹 by Redox Interactive',
            'color: #21201f; font-size: 14px; font-family:system-ui; background: #f4f4f4; padding: 6px 12px 6px 6px;'
        );

        const css = createCSS();
        document.head.appendChild(css);

        const html = createHTML();
        document.body.appendChild(html);

        // Fetch HTML elements reference
        splashElem = document.getElementById('application-splash-wrapper');
        runnerContainerElem = document.getElementById('runner-container');
        maskElem = document.getElementById('bar-mask');

        
        // In case some assets are too big to be properly transformed to base 64, you can load them on preload.
        app.on('preload:start', function() {
            // var exampleAsset = app.assets.find('example_name.png');
            // if (exampleAsset)
            // {
            //     var exampleImage = document.getElementById('example-id');
            //     exampleImage.src = exampleAsset.getFileUrl();
            // }
        });

        app.on('preload:end', function() {
            // app.off('preload:progress', setProgress);
        });
        app.on('preload:progress', setProgress);

        if (autoHideLoadingScreen) {
            app.on('start', endLoadingScreen);
        } else {
            app.on('hideLoadingScreen', endLoadingScreen);
        }

        function endLoadingScreen() {
            app.off('preload:progress', setProgress);
            hideSplash();
        }
    };

    // Build HTML structure of loadingscreen
    const createHTML = () =>
    {
        const wrapper = document.createElement('div');
        wrapper.id = 'application-splash-wrapper';

        if (BG_MODE === BG_IMAGE) {
            if (!imageSource.background || imageSource.backgroundImage === '') {
                console.log("imageSource.background not defined");
            }

            const background = document.createElement('img');
            wrapper.appendChild(background);
            background.id = 'background';
            background.src = imageSource.backgroundImage;
        }

        const splashItems = document.createElement('div');
        splashItems.id = 'splash-items';
        wrapper.appendChild(splashItems);

        if (BG_GLOW) {
            if (!imageSource.backgroundGlow || imageSource.backgroundGlow === '') {
                console.log("imageSource.backgroundGlow not defined");
            }

            const background_glow = document.createElement('div');
            background_glow.id = 'background_glow';
            splashItems.appendChild(background_glow);
        }

        // --------------- FIXED IMAGE (HA150 specific) ----------
        if (FIXED_IMAGE) {
            const fixedLogoWrapper = document.createElement('div');
            fixedLogoWrapper.id = 'fixed-logo-wrapper';
            wrapper.appendChild(fixedLogoWrapper);

            if (!imageSource.fixedLogo || imageSource.fixedLogo === '') {
                console.log("imageSource.fixedLogo not defined");
            }
            const fixedLogo = document.createElement('div');
            fixedLogo.id = 'fixed-logo';
            fixedLogoWrapper.appendChild(fixedLogo);

            if (!imageSource.fixedBackground || imageSource.fixedBackground === '') {
                console.log("imageSource.fixedBackground not defined");
            }
            const fixedBackground = document.createElement('div');
            fixedBackground.id = 'fixed-background';
            wrapper.appendChild(fixedBackground);

            if (!imageSource.fixedImage || imageSource.fixedImage === '') {
                console.log("imageSource.fixedImage not defined");
            }
            const fixedImage = document.createElement('div');
            fixedImage.id = 'fixed-image';
            wrapper.appendChild(fixedImage);
        }

        // ------------------- IMAGES -------------------
        if (LOGO_PRIMARY || LOGO_SECONDARY) {
            const imageGroupContainer = document.createElement('div');
            imageGroupContainer.id = 'image-group-container';
            splashItems.appendChild(imageGroupContainer);

            if(LOGO_PRIMARY) {
                if (!imageSource.logo || imageSource.logo === '') {
                    console.log("imageSource.logo not defined");
                }

                const logoContainer = document.createElement('div');
                logoContainer.id = 'logo-container';
                imageGroupContainer.appendChild(logoContainer);

                const logo = document.createElement('img');
                logo.id = 'logo';
                logo.src = imageSource.logo;
                logoContainer.appendChild(logo);
            }

            if (LOGO_SECONDARY) {
                if (!imageSource.logo2 || imageSource.logo2 === '') {
                    console.log("imageSource.logo2 not defined");
                }

                const logoContainer2 = document.createElement('div');
                logoContainer2.id = 'logo-container-second';
                imageGroupContainer.appendChild(logoContainer2);

                const logo2 = document.createElement('img');
                logo2.id = 'logo';
                logo2.src = imageSource.logo2;
                logoContainer2.appendChild(logo2);
            }
        }
        // ----------------------------------------------

        // ---------------- PROGRESS-BAR ----------------
        const pbGroupContainer = document.createElement('div');
        pbGroupContainer.id = 'pb-group-container';
        splashItems.appendChild(pbGroupContainer);

        const pbContainer = document.createElement('div');
        pbContainer.id = 'pb-container';
        pbGroupContainer.appendChild(pbContainer);

        if (USE_IMAGES) {  // Will there also be a color background or a gradient?
            if (!imageSource.pbBackground || imageSource.pbBackground === '') {
                console.log("imageSource.pbBackground not defined");
            }

            const pbBackground = document.createElement('img');
            pbBackground.id = 'pb-background';
            pbBackground.src = imageSource.pbBackground;
            pbContainer.appendChild(pbBackground);
        }

        const barMask = document.createElement('div');
        barMask.id = 'bar-mask';
        pbContainer.appendChild(barMask);

        if (USE_IMAGES && SHOW_BORDER) {
            if (!imageSource.pbBorder || imageSource.pbBorder === '') {
                console.log("imageSource.pbBorder not defined");
            }

            const pbBorder = document.createElement('img');
            pbBorder.id = 'pb-border';
            pbBorder.src = imageSource.pbBorder;
            pbContainer.appendChild(pbBorder);
        }

        if (USE_IMAGES) {
            if (!imageSource.bar || imageSource.bar === '') {
                console.log("imageSource.bar not defined");
            }
        } else {
            const bar = document.createElement('div');
            bar.id = 'bar';
            barMask.appendChild(bar);
        }

        // ----------------------------------------------

        // ------------------- RUNNER -------------------
        if (RUNNER) {
            const runnerContainer = document.createElement('div');
            runnerContainer.id = 'runner-container';
            pbContainer.appendChild(runnerContainer);

            const runner = document.createElement('img');
            runner.id = 'runner';
            runner.src = imageSource.runner;
            runnerContainer.appendChild(runner);

            if(GLOSS) {
                const runnerGloss = document.createElement('img');
                runnerGloss.id = 'runner-gloss';
                runnerGloss.src = imageSource.runnerGloss;
                runnerContainer.appendChild(runnerGloss);
            }
        }
        // ----------------------------------------------

        return wrapper;
    };

    // Add styling to loadingscreen
    const createCSS = () =>
    {
        // Add gradient to background
        const backgroundGradient = BG_MODE === BG_GRADIENT ?
            [
                'background: -moz-linear-gradient(' + GRADIENT_ROTATION + 'deg, ' + BG_GRADIENT_START + ' 0%, ' + BG_GRADIENT_END + ' 100%);',
                'background: -webkit-linear-gradient(' + GRADIENT_ROTATION + 'deg,  ' + BG_GRADIENT_START + ' 0%, ' + BG_GRADIENT_END + ' 100%);',
                'background: linear-gradient(' + GRADIENT_ROTATION + 'deg,  ' + BG_GRADIENT_START + ' 0%, ' + BG_GRADIENT_END + ' 100%);',
                'filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'' + BG_GRADIENT_START +  '\', endColorstr=\'' + BG_GRADIENT_END + '\',GradientType=0 );',
            ] : [];

        // Add repeatable image to background
        const backgroundRepeat = BG_MODE === BG_REPEAT ?
            [
                'background-image: url("' + imageSource.backgroundRepeat + '");',
                'background-repeat: repeat-x;',
                'background-size: auto 100%;',
            ] : [];

        // Set a color as progress bar background
        const pbColor = PB_MODE === PB_COLOR ?
            [
                'background-color: '+ PB_COLOR_VALUE + ';',
                'border-radius: ' + RADIUS + 'px;',
                'max-width: 100%;',
                'max-height: 100%;',
            ] : [];

        // Set a gradient as progress bar background
        const pbGradient = !USE_IMAGES && PB_MODE === PB_GRADIENT ?
            [
                'background: -moz-linear-gradient(' + PB_GRADIENT_ROTATION + 'deg, ' + PB_GRADIENT_START + ' 0%, ' + PB_GRADIENT_END + ' 100%);',
                'background: -webkit-linear-gradient(' + PB_GRADIENT_ROTATION + 'deg, ' + PB_GRADIENT_END + ' 100%);',
                'background: linear-gradient(' + PB_GRADIENT_ROTATION + 'deg,  ' + PB_GRADIENT_START + ' 0%, ' + PB_GRADIENT_END + ' 100%);',
                'filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'' + PB_GRADIENT_START +  '\', endColorstr=\'' + PB_GRADIENT_END + '\',GradientType=0 );',
                'border-radius: ' + RADIUS + 'px;',
                'max-width: 100%;',
                'max-height: 100%;',
            ] : [];

        // Set the border with a color
        const pbBorder = !USE_IMAGES && SHOW_BORDER ?
            [
                'border: ' + BORDER_WIDTH + 'px solid '+ BORDER_COLOR_VALUE + ';',
                'border-radius: ' + RADIUS + 'px;',
            ] : [];

        // Set radius for the mask
        const barMaskForColor = !USE_IMAGES && BAR_MODE === BAR_COLOR ?
            [
                // 'border-radius: ' + RADIUS + 'px;',
                'height: 100%;',
            ] : [];

        const barTween = TWEEN_PROGRESS ?
            [
                'transition: width 2s;',
            ] : [];
        // Set a color and radius for the progress background
        const barColor = !USE_IMAGES && BAR_MODE === BAR_COLOR ?
            [
                'background-color: '+ BAR_COLOR_VALUE + ';',
                'border-radius: ' + (RADIUS * 0.666) + 'px;',
            ] : [];

        // Set a gradient and radius for the progress background
        const barGradient = !USE_IMAGES && BAR_MODE === BAR_GRADIENT ?
            [
                'background: -moz-linear-gradient(' + BAR_GRADIENT_ROTATION + 'deg, ' + BAR_GRADIENT_START + ' 0%, ' + BAR_GRADIENT_END + ' 100%);',
                'background: -webkit-linear-gradient(' + BAR_GRADIENT_ROTATION + 'deg,  ' + BAR_GRADIENT_START + ' 0%, ' + BAR_GRADIENT_END + ' 100%);',
                'background: linear-gradient(' + BAR_GRADIENT_ROTATION + 'deg,  ' + BAR_GRADIENT_START + ' 0%, ' + BAR_GRADIENT_END + ' 100%);',
                'filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'' + BAR_GRADIENT_START +  '\', endColorstr=\'' + BAR_GRADIENT_END + '\',GradientType=0 );',
                'border-radius: ' + (RADIUS * 0.666) + 'px;',
            ] : [];

        const pbColorSettings = !USE_IMAGES ?
            [
                '#pb-group-container {',
                    // 'border: 1px solid green;',
                    'max-width: 100%;',
                    'max-height: 100%;',

                    'width: 0;',
                    'margin-left:' + OFFSET_X + '%;',
                    'margin-top:' + OFFSET_Y + '%;',

                    'display: flex;',
                    'align-items: center;',
                    'flex-direction: column;',
                    'justify-content: center;',

                    'display: -webkit-flex;',
                    '-webkit-align-items: center;',
                    '-webkit-flex-direction: column;',
                    '-webkit-justify-content: center;',
                '}',

                '#pb-container {',
                    'position: relative;',

                    'min-height: 80px;',
                    'min-width: 400px;',

                    'display: flex;',
                    'align-items: center;',
                    'flex-direction: column;',
                    'justify-content: center;',

                    'display: -webkit-flex;',
                    '-webkit-align-items: center;',
                    '-webkit-flex-direction: column;',
                    '-webkit-justify-content: center;',

                    ...pbColor,
                    ...pbGradient,
                    ...pbBorder,
                '}',

                '@media screen and (max-width: 800px) {',
                    '#pb-container {',
                        'min-height: 50px;',
                        'min-width: 250px;',
                    '}',
                '}',

                '#pb-background {',
                    'height: 50%;', // schauen wie man das fixen kann
                    'width: 50%;', // schauen wie man das fixen kann
                '}',

                '#pb-border {',
                    'position: absolute;',
                    'top: 0px;',
                    'left: 0px;',
                '}',

                '#bar-mask {',
                    'position: absolute;',
                    'top: 0;',
                    'left: 0;',

                    'width: 100%;',
                    'height: 100%;',
                    'clip-path: inset(0px 100% 0px 0px);',

                    ...barTween,
                    // In case the bar should be colored instead of an image, adjust these values
                    ...barMaskForColor,
                '}',

                '#bar {',
                    'width: auto;',
                    'height: 100%;',
                    ...barColor,
                    ...barGradient,
                '}',
            ] : [];

        // Styling for progress bar when using images
        const pbImageSettings = USE_IMAGES ?
            [
                '#pb-group-container {',
                    'max-height: ' + MAX_BAR_HEIGHT + 'px;',
                    'min-height: ' + MIN_BAR_HEIGHT + 'px;',
                    'height: 100%;',
                    'margin-left:' + OFFSET_X + '%;',
                    'margin-top:' + OFFSET_Y + '%;',

                    'display: flex;',
                    'align-items: center;',
                    'flex-direction: column;',
                    'justify-content: center;',

                    'display: -webkit-flex;',
                    '-webkit-align-items: center;',
                    '-webkit-flex-direction: column;',
                    '-webkit-justify-content: center;',
                '}',
                '@media only screen and (max-width: 600px) {',
                    '#pb-group-container {',
                        'height: 35px !important;',
                    '}',
                '}',
                '#pb-container {',
                    'display: inline-block;',
                    'position: relative;',
                    'max-height: 100%;',
                    'aspect-ratio: ' + pbBgPixelRatio + ';',
                '}',

                '#pb-background {',
                    'height: 100%;',
                    'width: 100%;',
                '}',

                '#pb-border {',
                    'position: absolute;',
                    'top: 0px;',
                    'left: 0px;',

                    'height: 100%;',
                    'width: auto;',
                '}',

                '#bar-mask {',
                    'position: absolute;',
                    'top: 0;',
                    'left: 0;',

                    'width: 100%;',
                    'height: 100%;',
                    'clip-path: inset(0px 100% 0px 0px);',

                    `background-image: url("${ imageSource.bar }");`,
                    'background-size: contain;',

                    ...barTween,
                '}',

                '#bar {',
                    'width: auto;',
                    'height: 100%;',
                '}',
            ] : [];


        // Add the config for the runner animation
        const runnerAnimation = RUNNER_ANIMATION ?
            [
                '#runner {',
                    'animation: infinite-spinning 2s infinite linear;',
                '}',
                '@-webkit-keyframes infinite-spinning {',
                    'from { transform: rotate(0deg); }',
                    'to { transform: rotate(360deg); }',
                '}',
                '@-moz-keyframes infinite-spinning {',
                    'from { transform: rotate(0deg); }',
                    'to { transform: rotate(360deg); }',
                '}',
                '@-o-keyframes infinite-spinning {',
                    'from { transform: rotate(0deg); }',
                    'to { transform: rotate(360deg); }',
                '}',
                '@keyframes infinite-spinning {',
                    'from { transform: rotate(0deg); }',
                    'to { transform: rotate(360deg); }',
                '}',
                '#runner-gloss {',
                    'position: absolute;',
                    'opacity: .9;',
                '}',
            ] : [];

        const fixedImageSettings = FIXED_IMAGE ?
            [
                '#fixed-image {',
                    'height: ' + X_HEIGHT * 4.5 + 'px;',
                    'width: ' + X_HEIGHT * 4.5 + 'px;',
                    'position: fixed;',
                    'right: ' + X_HEIGHT + 'px;',
                    'bottom: ' + X_HEIGHT + 'px;',
                    'background-image: url("' + imageSource.fixedImage + '");',
                    'background-repeat: no-repeat;',
                    'background-size: contain;',
                '}',

                '#fixed-background {',
                    'height: ' + X_HEIGHT * 4.5 * 3 + 'px;',
                    'width: ' + X_HEIGHT * 4.5 * 3 * 1.44 + 'px;',
                    'position: fixed;',
                    'right: -' + X_HEIGHT + 'px;',
                    'bottom: -' + X_HEIGHT * 3.5 + 'px;',
                    'background-image: url("' + imageSource.fixedBackground + '");',
                    'background-repeat: no-repeat;',
                    'background-size: contain;',
                '}',

                '#fixed-logo {',
                    'height: ' + X_HEIGHT * 4.5 + 'px;',
                    'width: ' + X_HEIGHT * 4.5 * 3 + 'px;',
                    'background-image: url("' + imageSource.fixedLogo + '");',
                    'background-repeat: no-repeat;',
                    'background-size: contain;',
                '}',

                '#fixed-logo-wrapper {',
                    'display: flex;',
                    'align-items: flex-end;',
                    'height: ' + X_HEIGHT * 5.5 + 'px;',
                    'width: ' + X_HEIGHT * 4.5 * 3 + 'px;',
                    'position: fixed;',
                    'top: 0px;',
                    'left: ' + X_HEIGHT + 'px;',
                    'background-color: #FFA500;',
                '}',
            ] : [];

        // General styling
        const css = [
            'body {',
                'background-color: ' + BG_COLOR_VALUE + ';',
            '}',

            'body,',
            'canvas {',
                '-webkit-touch-callout: none;',
                '-webkit-user-select: none;',
                '-khtml-user-select: none;',
                '-moz-user-select: none;',
                '-ms-user-select: none;',
                'user-select: none;',
                'outline: 0;',
                '-webkit-tap-highlight-color: rgba(255, 255, 255, 0);',
            '}',

            '#application-splash-wrapper {',
                'height: 100vh;',
                'width: 100vw;',
                'position: absolute;',
                'bottom: 0;',
                'left: 0;',
                'right: 0;',
                'top: 0;',

                'display: flex;',
                'align-items: center;',
                'flex-direction: column;',
                'justify-content: center;',

                'display: -webkit-flex;',
                '-webkit-align-items: center;',
                '-webkit-flex-direction: column;',
                '-webkit-justify-content: center;',

                'background-color: ' + BG_COLOR_VALUE + ';',

                ...backgroundGradient,
                ...backgroundRepeat,

                'z-index: 1;',
            '}',

            '#application-splash-wrapper div {',
                'line-height: 0;',
            '}',

            '#background {',
                'position: absolute;',
                'left: 0;',
                'top: 0;',
                'width: 100%;',
                'height: 100%;',
                'object-fit: cover;',
            '}',

            '#splash-items {',
                'width: 80%;',
                'height: 80%;',
                'position: relative;',

                'display: flex;',
                'align-items: center;',
                'flex-direction: column;',
                'justify-content: center;',

                'display: -webkit-flex;',
                '-webkit-align-items: center;',
                '-webkit-flex-direction: column;',
                '-webkit-justify-content: center;',
            '}',

            '#background_glow {',
                'height: 400px;',
                'width: 400px;',
                'position: absolute;',
                'margin-left:' + GLOW_H_POSITION + 'px;',
                'transform: scale(' + GLOW_SCALE + ');',
                'opacity: 0.5;',
                'z-index: -5;',
                'background-image: url("' + imageSource.backgroundGlow + '");',
                'background-repeat: no-repeat;',
            '}',



            // -------------------- LOGOS -------------------
            '#image-group-container {',
                'height: 50%;',
                'max-height: ' + LOGO_MAX_HEIGHT + 'px;',
                'margin-left:' + LOGO_H_POSITION + '%;',

                'display: flex;',
                'align-items: center;',
                'flex-direction: column;',
                'justify-content: center;',

                'display: -webkit-flex;',
                '-webkit-align-items: center;',
                '-webkit-flex-direction: column;',
                '-webkit-justify-content: center;',
            '}',

            '#image-group-container img {',
                'max-width: 100%;',
                'max-height: 100%;',
            '}',

            '#logo-container {',
                'height: ' + LOGO_SCALE + '%;',
                'margin-bottom:' + LOGO_BOTTOM_DISTANCE + 'px;',
                'display: flex;',
                'align-items: center;',
                'flex-direction: column;',
                'justify-content: center;',

                'display: -webkit-flex;',
                '-webkit-align-items: center;',
                '-webkit-flex-direction: column;',
                '-webkit-justify-content: center;',
            '}',

            '#logo-container-second {',
                'height: ' + SECOND_LOGO_SCALE + '%;',
                'margin-left:' + SECOND_LOGO_H_POSITION + 'px;',
                'margin-bottom:' + SECOND_LOGO_BOTTOM_DISTANCE + 'px;',
                'display: flex;',
                'align-items: center;',
                'flex-direction: column;',
                'justify-content: center;',

                'display: -webkit-flex;',
                '-webkit-align-items: center;',
                '-webkit-flex-direction: column;',
                '-webkit-justify-content: center;',
            '}',

            '#logo {',
                'max-width: 100%;',
                'max-height: 100%;',
            '}',

            '@media screen and (max-width: 800px) {',
                '#logo {',
                    'height: auto;',
                    'max-width: 80%;',
                '}',
            '}',
            // ----------------------------------------------


            // ---------------- PROGRESS-BAR ----------------
            ...pbImageSettings, // Styling when using images
            ...pbColorSettings, // Styling for when using colors/gradients
            // ----------------------------------------------


            // ---------------- FIXED-IMAGE ----------------
            ...fixedImageSettings, // Styling when using fixed images
            // ----------------------------------------------


            // ------------------- RUNNER -------------------
            '#runner-container {',
                'height: 100%;',
                'position: absolute;',
                'top: 0;',
                'left: -2%;',

                'display: flex;',
                'align-items: center;',
                'flex-direction: column;',
                'justify-content: center;',

                'display: -webkit-flex;',
                '-webkit-align-items: center;',
                '-webkit-flex-direction: column;',
                '-webkit-justify-content: center;',
            '}',

            '#runner-container > * {',
                'width: auto;',
                'height: ' + RUNNER_HEIGHT + '%;',
            '}',

            ...runnerAnimation
        // ----------------------------------------------

        ].join('\n');

        const style = document.createElement('style');
        style.type = 'text/css';

        if (style.styleSheet)
        {
            style.styleSheet.cssText = css;
        }
        else
        {
            style.appendChild(document.createTextNode(css));
        }

        return style;
    };

    // @param value [Float] A numeric value between 0 and 1, for example 0.5 <==> shows 50% of the progress
    const setProgress = (value) =>
    {
        value = Math.min(1, Math.max(0, value));

        if (maskElem)
        {
            const clipWidth = Math.floor(100 - value * 100);
            maskElem.style.clipPath = `inset(0px ${clipWidth}% 0px 0px)`;

            // // In case the bar should be colored
            // maskElem.style.width = value * 96 + '%';
        }

        if (runnerContainerElem)
        {
            // left: -2% -> left: 92%
            runnerContainerElem.style.marginLeft = (-5 + value * 94) + '%';
        }
    };

    const hideSplash = () =>
    {
        splashElem.parentElement?.removeChild(splashElem);
    };

    showLoadingScreen();
});